import React, { useState, useEffect } from "react";
import {
  Box,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  TextField,
  Typography,
  Container,
  TablePagination,
  CircularProgress,
  IconButton,
  Grid,
  InputAdornment,
} from "@mui/material";
import {
  Store as StoreIcon,
  AddLocation as AddLocationIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Search,
} from "@mui/icons-material";
import Swal from "sweetalert2";
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";

function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`tabpanel-${index}`}
      aria-labelledby={`tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const Locations = () => {
  const [tabValue, setTabValue] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");
  const [locations, setLocations] = useState([]);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalLocations, setTotalLocations] = useState(0);
  const [loading, setLoading] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [selectedLocationId, setSelectedLocationId] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    code: "",
    address: "",
  });
  const [errors, setErrors] = useState({});
  const [buttonLoading, setButtonLoading] = useState(false); // Added for button loader

  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 1500,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
    customClass: {
      container: "swal-toast-container",
      popup: "swal-toast-popup",
    },
  });

  useEffect(() => {
    const styleSheet = document.createElement("style");
    styleSheet.textContent = `
      .swal-toast-container {
        z-index: 9999 !important;
      }
      .swal-toast-popup {
        font-family: 'Inter', sans-serif;
        font-size: 14px;
      }
    `;
    document.head.appendChild(styleSheet);
    return () => document.head.removeChild(styleSheet);
  }, []);

  const fetchLocations = async () => {
    setLoading(true);
    try {
      const response = await apiRequest({
        ...API.locationsList,
        params: {
          paginate: true,
          page: page + 1,
          per_page: rowsPerPage,
          search: searchQuery,
        },
      });
      setLocations(response.data.data);
      setTotalLocations(response.data?.total);
    } catch (error) {
      setLocations([]);
      setTotalLocations(0);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLocations();
  }, [page, rowsPerPage, searchQuery]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
    setEditMode(false);
    setFormData({ name: "", code: "", address: "" });
    setErrors({});
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
    setErrors((prev) => ({
      ...prev,
      [name]: "",
    }));
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = "Name is required";
    if (!formData.code.trim()) newErrors.code = "Code is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSaveChanges = async () => {
    if (!validateForm()) return;

    setButtonLoading(true);

    const data = new FormData();

    data.append("name", formData.name);
    data.append("code", formData.code);
    data.append("address", formData.address);

    try {
      const response = await apiRequest({
        ...(editMode
          ? {
              ...API.editLocation(selectedLocationId),
            }
          : {
              ...API.addLocation,
            }),

        data,
      });

      Toast.fire({
        icon: "success",
        title:
          response?.message ||
          (editMode ? "Location updated" : "Location added"),
      });

      setTabValue(0);
      fetchLocations();
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error?.message || "Failed to save location",
      });
    } finally {
      setButtonLoading(false);
    }
  };

  const handleCancel = () => {
    setEditMode(false);
    setFormData({ name: "", code: "", address: "" });
    setErrors({});
  };

  const handleEdit = async (id) => {
    try {
      const response = await apiRequest({
        ...API.locationDetails(id),
      });

      const location = response?.data;

      setFormData({
        name: location?.name || "",
        code: location?.code || "",
        address: location?.address || "",
      });

      setSelectedLocationId(id);
      setEditMode(true);
      setTabValue(1);
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error?.message || "Failed to fetch location details",
      });
    }
  };

  const handleDelete = (id) => {
    Swal.fire({
      title: "Are you sure?",
      text: "You won't be able to revert this!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#43B02A",
      cancelButtonColor: "#C92A20",
      confirmButtonText: "Yes, delete it!",
      cancelButtonText: "No, cancel",
      customClass: {
        container: "swal-toast-container",
        popup: "swal-toast-popup",
      },
    }).then(async (result) => {
      if (result.isConfirmed) {
        try {
          const response = await apiRequest({
            ...API.deleteLocation(id),
          });

          Toast.fire({
            icon: "success",
            title: response?.message || "Location deleted successfully",
          });

          fetchLocations();
        } catch (error) {
          Toast.fire({
            icon: "error",
            title: error?.message || "Failed to delete location",
          });
        }
      }
    });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <Grid container>
      <Box sx={{ mb: 2 }}>
        <TextField
          placeholder="Search Locations..."
          value={searchQuery}
          onChange={(e) => {
            setSearchQuery(e.target.value);
            setPage(0);
          }}
          size="small"
          sx={{
            "& .MuiOutlinedInput-root": {
              borderRadius: 8,
              backgroundColor: "#fff",
              "& fieldset": { borderColor: "#e0e0e0" },
              "&:hover fieldset": { borderColor: "#bdbdbd" },
              "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
              "& input": {
                padding: { xs: "6px 10px", sm: "8px 12px" },
                fontSize: { xs: "0.75rem", sm: "0.875rem" },
              },
            },
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <Search sx={{ color: "#666", fontSize: { xs: 18, sm: 20 } }} />
              </InputAdornment>
            ),
          }}
        />
      </Box>

      <Paper
        sx={{
          width: "100%",
          borderRadius: 2,
          boxShadow: 1,
          overflow: "hidden",
        }}
      >
        <Box sx={{ borderBottom: "1px solid #e0e0e0" }}>
          <Tabs
            value={tabValue}
            onChange={handleTabChange}
            sx={{
              "& .MuiTab-root": {
                textTransform: "none",
                fontWeight: 500,
                minHeight: 48,
                borderRadius: 1,
              },
              "& .Mui-selected": {
                backgroundColor: "#F97316 !important",
                color: "white !important",
              },
              "& .MuiTabs-indicator": { backgroundColor: "#fff", height: 2 },
            }}
          >
            <Tab
              icon={<StoreIcon />}
              label="Location List"
              iconPosition="start"
              sx={{ gap: 1 }}
            />
            <Tab
              icon={editMode ? <EditIcon /> : <AddLocationIcon />}
              label={editMode ? "Update Location" : "Add Location"}
              iconPosition="start"
              sx={{ gap: 1 }}
            />
          </Tabs>
        </Box>

        <TabPanel value={tabValue} index={0}>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: "bold" }}>ID</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Name</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Code</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Address</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={5} align="center">
                      Loading...
                    </TableCell>
                  </TableRow>
                ) : Array.isArray(locations) && locations.length > 0 ? (
                  locations.map((location) => (
                    <TableRow
                      key={location.id}
                      sx={{ "&:hover": { backgroundColor: "#f9f9f9" } }}
                    >
                      <TableCell>{location.id}</TableCell>
                      <TableCell>{location.name}</TableCell>
                      <TableCell>{location.code}</TableCell>
                      <TableCell>{location.address || "N/A"}</TableCell>
                      <TableCell>
                        <Box sx={{ display: "flex", gap: 1 }}>
                          <Button
                            variant="contained"
                            size="small"
                            onClick={() => handleEdit(location.id)}
                            sx={{
                              backgroundColor: "#3B82F6",
                              "&:hover": { backgroundColor: "#3B82F6" },
                              textTransform: "none",
                              borderRadius: 3,
                              fontSize: "12px",
                              lineHeight: 1.5,
                            }}
                          >
                            Edit
                          </Button>
                          <IconButton
                            size="small"
                            onClick={() => handleDelete(location.id)}
                            sx={{
                              backgroundColor: "#C92A20",
                              "&:hover": { backgroundColor: "#b12419" },
                              color: "#fff",
                              width: "32px",
                              height: "32px",
                            }}
                          >
                            <DeleteIcon fontSize="small" />
                          </IconButton>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={5} align="center">
                      No data available
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
          <TablePagination
            rowsPerPageOptions={[5, 10, 25]}
            component="div"
            count={totalLocations}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </TabPanel>

        <TabPanel value={tabValue} index={1}>
          <Box sx={{ maxWidth: 600, mx: "auto" }}>
            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Name
            </Typography>
            <TextField
              fullWidth
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              error={!!errors.name}
              helperText={errors.name}
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />
            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Code
            </Typography>
            <TextField
              fullWidth
              name="code"
              value={formData.code}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              error={!!errors.code}
              helperText={errors.code}
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />
            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Address
            </Typography>
            <TextField
              fullWidth
              name="address"
              value={formData.address}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />
            <Box sx={{ display: "flex", gap: 2, justifyContent: "flex-end" }}>
              <Button
                variant="contained"
                onClick={handleSaveChanges}
                disabled={buttonLoading}
                sx={{
                  backgroundColor: "#43B02A",
                  "&:hover": { backgroundColor: "#3a9624" },
                  textTransform: "none",
                  px: 3,
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                }}
              >
                {buttonLoading && (
                  <CircularProgress size={20} sx={{ color: "white" }} />
                )}
                {editMode ? "Update Location" : "Save Changes"}
              </Button>
              <Button
                variant="contained"
                onClick={handleCancel}
                sx={{
                  backgroundColor: "#C92A20",
                  "&:hover": { backgroundColor: "#b12419" },
                  textTransform: "none",
                  px: 3,
                }}
              >
                Cancel
              </Button>
            </Box>
          </Box>
        </TabPanel>
      </Paper>
    </Grid>
  );
};

export default Locations;
